use std::{fs,io::{Read,Write},path::{Path,PathBuf,Component},error::Error};
use sha2::{Sha256,Digest};
use serde_json::{Value,json};
type R<T>=Result<T,Box<dyn Error>>;
fn hash(p:&Path)->R<(u64,String)>{let mut f=fs::File::open(p)?;let mut b=vec![0u8;1048576];let(mut h,mut n)=(Sha256::new(),0u64);loop{let k=f.read(&mut b)?;if k==0{break}h.update(&b[..k]);n+=k as u64;}Ok((n,format!("{:x}",h.finalize())))}
fn safe(s:&str)->R<PathBuf>{let p=PathBuf::from(s);if p.as_os_str().is_empty()||p.components().any(|c|!matches!(c,Component::Normal(_))){return Err("Ruta no relativa segura".into())}Ok(p)}
fn save(p:&Path,v:&Value)->R<()>{let mut f=fs::OpenOptions::new().write(true).create_new(true).open(p)?;f.write_all(&serde_json::to_vec_pretty(v)?)?;Ok(())}
fn walk(base:&Path,p:&Path,items:&mut Vec<Value>)->R<()>{let m=fs::symlink_metadata(p)?;if m.file_type().is_symlink(){return Err("Enlace no admitido".into())}if m.is_dir(){let mut es=fs::read_dir(p)?.map(|e|e.map(|x|x.path())).collect::<Result<Vec<_>,_>>()?;es.sort();for e in es{walk(base,&e,items)?}}else if m.is_file(){let(n,h)=hash(p)?;items.push(json!({"ruta":p.strip_prefix(base)?.to_string_lossy().replace('\\',"/"),"bytes":n,"sha256":h}));}else{return Err("Tipo especial no admitido".into())}Ok(())}
fn main()->R<()>{let a:Vec<String>=std::env::args().collect();match a.get(1).map(String::as_str){
 Some("manifest")=>{let base=fs::canonicalize(&a[2])?;let mut v=Vec::new();for r in &a[4..]{walk(&base,&base.join(safe(r)?),&mut v)?}v.sort_by_key(|x|x["ruta"].as_str().unwrap().to_owned());for w in v.windows(2){if w[0]["ruta"]==w[1]["ruta"]{return Err("Ruta duplicada".into())}}let n:u64=v.iter().map(|x|x["bytes"].as_u64().unwrap()).sum();save(Path::new(&a[3]),&json!({"archivos":v,"cantidad":v.len(),"bytes":n,"metodo":"Lectura integra y SHA-256 en Rust"}))?;println!("{} archivos; {} bytes",v.len(),n);},
 Some("check")=>{let m:Value=serde_json::from_slice(&fs::read(&a[3])?)?;let base=fs::canonicalize(&a[2])?;let mut total=0;let rows=m["archivos"].as_array().ok_or("Sin archivos")?;for r in rows{let p=base.join(safe(r["ruta"].as_str().ok_or("Sin ruta")?)?);if !fs::canonicalize(&p)?.starts_with(&base)||fs::symlink_metadata(&p)?.file_type().is_symlink(){return Err("Fuera de perimetro".into())}let(n,h)=hash(&p)?;if r["bytes"]!=n||r["sha256"]!=h{return Err(format!("Discordancia: {}",r["ruta"]).into())}total+=n;}save(Path::new(&a[4]),&json!({"conforme":true,"cantidad":rows.len(),"bytes":total,"manifiesto_sha256":hash(Path::new(&a[3]))?.1,"metodo":"Relectura integra, longitud y SHA-256 en Rust"}))?;println!("Cotejo conforme: {} archivos",rows.len());},
 Some("equal")=>{let mut f=fs::File::open(&a[2])?;let mut g=fs::File::open(&a[3])?;let(mut b,mut c)=(vec![0u8;1048576],vec![0u8;1048576]);loop{let n=f.read(&mut b)?;let mut k=0;while k<n{let z=g.read(&mut c[k..n])?;if z==0{return Err("Truncado".into())}k+=z;}if b[..n]!=c[..n]{return Err("Bytes distintos".into())}if n==0{if g.read(&mut c[..1])?!=0{return Err("Exceso de bytes".into())}break}}let(n,h)=hash(Path::new(&a[2]))?;save(Path::new(&a[4]),&json!({"conforme":true,"bytes":n,"sha256":h,"igualdad_integra_bytes":true}))?;println!("Igualdad integra conforme: {n} bytes; {h}");},
 Some("hash")=>{let(n,h)=hash(Path::new(&a[2]))?;println!("{}",json!({"bytes":n,"sha256":h}));},
 Some("stage-pdf")=>{let base=Path::new(&a[2]);let dest=Path::new(&a[3]);fs::create_dir_all(dest)?;let publication:Value=serde_json::from_slice(&fs::read(base.join("custodia-mcp/PUBLICACION.json"))?)?;let prefix="laboratorio/ensayo-ia-y-observabilidad/modelos-de-ia/model-context-protocol/0.1.4-pdf-preparacion/";let mut records=vec![];for r in publication["archivos"].as_array().ok_or("Sin publicacion")?{let Some(relative)=r["ruta"].as_str().ok_or("Ruta")?.strip_prefix(prefix) else {continue};if !(relative.starts_with("lector/")||relative.starts_with("mcp-documental-0.1.4-pdf/")||relative.starts_with("correccion/")){continue}let p=safe(relative)?;let src=base.join(&p);let(n,h)=hash(&src)?;if r["bytes"]!=n||r["sha256"]!=h{return Err(format!("Fuente no coincide con publicacion: {relative}").into())}let d=dest.join(&p);fs::create_dir_all(d.parent().unwrap())?;fs::copy(src,&d)?;records.push(json!({"ruta":relative,"bytes":n,"sha256":h}));}let rel="lector/tests/fixtures/hairy-cell-leukemia.pdf";let p=base.join(rel);let(n,h)=hash(&p)?;if h!="21322ed388c999bd0713ba5ec5c7ab34402d4bb4cd6100903aa5ea6d8bf35d9c"{return Err("PDF no coincide".into())}if !dest.join(rel).exists(){fs::create_dir_all(dest.join(rel).parent().unwrap())?;fs::copy(&p,dest.join(rel))?;records.push(json!({"ruta":rel,"bytes":n,"sha256":h}));}save(&dest.join("FUENTES-INSTALACION.json"),&json!({"revision":"3f12e5054523f313ce148d37f0bdaee16bcff98a","archivos":records,"cantidad":records.len()}))?;println!("Preparacion fiel a publicacion: {} archivos",records.len());},
 _=>return Err("Modo desconocido".into())}Ok(())}
